void Output_Overlay_CaptureGameSnapshot(void)
{
    // The scene drawn once more, into the capture: the PowerVR's render to
    // texture, where the desktop draws to a framebuffer object.
    if (!DC_PVR_BeginCaptureFrame()) {
        return;
    }
    Interpolation_Disable();
    Output_SwitchViewport(VIEWPORT_GAME);
    SceneCompositor_BeginScene();
    Output_Lights_BeginScene();
    Game_Draw(false);
    SceneCompositor_EndScene();
    Interpolation_Enable();
    DC_PVR_EndFrame();
}

void Output_Overlay_CaptureSnapshot(void)
{
    Output_Overlay_CaptureGameSnapshot();
}

// The scripts' snapshot layers (a cross fade from the last frame, the frame
// held while the next screen starts) hold a slot but keep nothing on the
// Dreamcast: capturing means drawing the scene again into a texture, which
// took the frame rate to nothing as Lara died, and drawing the capture
// covered the dying animation with a frozen picture. The slot is given and
// nothing is drawn; the fades to colour still work.
int32_t Output_Overlay_CaptureSnapshotSlot(void)
{
    return 0;
}

void Output_Overlay_DrawBackground(BACKGROUND_TYPE style, float opacity, const char *image_path)
{
    // Darkened, without the desktop's blur and desaturation.
    DC_PVR_DrawScreenCapture(1.0f - 0.6f * opacity);
}

void Output_Overlay_DrawBlackRectangle(const float opacity)
{
    Output_DrawScreenBlack(opacity);
}

// The title menu's picture (the gameflow's main_menu_picture).
void Output_Overlay_DrawImage(const char *file_name)
{
    DC_PVR_SetPicture(file_name);
    DC_PVR_DrawPicture(1.0f);
}

void Output_Overlay_DrawImageInBox(const char *file_name, OUTPUT_OVERLAY_BOX box, float opacity)
{
    DC_PVR_SetPicture(file_name);
    DC_PVR_DrawPictureBox(box.x0, box.y0, box.x1, box.y1, opacity);
}

// shortcut: in colour, only dimmed; desaturate if a mono picture shows up.
void Output_Overlay_DrawImageMono(const char *file_name, float intensity)
{
    DC_PVR_SetPicture(file_name);
    DC_PVR_DrawPicture(intensity);
}

void Output_Overlay_DrawLetterbox(void)
{
    Output_DrawScreenBlack(m_Fade);
    if (m_Letterbox <= 0.0f) {
        return;
    }
    const int32_t height = Viewport_GetHeight(VIEWPORT_UI);
    const int32_t width = Viewport_GetWidth(VIEWPORT_UI);
    const int32_t bar_height = (int32_t)(height * m_Letterbox);
    const RGBA_8888 black = { 0, 0, 0, 255 };
    Output_DrawScreenFlatQuad(0, 0, 0, width, bar_height, black);
    Output_DrawScreenFlatQuad(
        0, height - bar_height, 0, width, bar_height, black);
}

